// Package business holds the model of the business that owns a book.
//
// A business is the thing that owns money: the Personal Business of a
// person, and, tomorrow, the bakery of that same person. The book of
// accounts belongs to the business, and never to the person.
//
// The identity of a business is generated by the database, and it belongs to
// the business alone. The document ID of the owner is not its key: the owner
// is the owner, and a person may own more than one business. The personal
// business of a person is found through its owner, and the storage holds the
// rule that a person has exactly one of them.
//
// The package imports nothing but the standard library and the model of the
// person: the owner of a business IS a person, and the domain of the
// business speaks in the identity of the person.
package business

import (
	"fmt"
	"strings"
	"time"

	"github.com/witsaba/paca/packages/domain/user"
)

// ID is the identity of a business.
//
// The number is generated by the database: it is the counter of the business
// and not the document of a person. The type exists so that an identifier
// never travels as a plain integer by accident.
type ID int64

// Kind is the kind of a business.
type Kind string

const (
	// KindPersonal is the kind of the Personal Business of a person: the
	// book that holds the money of the person.
	KindPersonal Kind = "personal"

	// KindBusiness is the kind of a business that is not the personal one.
	//
	// The kind belongs to the vocabulary of the domain, and no use case
	// creates one yet: the personal business is the only one that is
	// created today.
	KindBusiness Kind = "business"
)

// kinds holds the kinds of a business, in the order they are presented.
var kinds = []Kind{
	KindPersonal,
	KindBusiness,
}

// AllKinds returns the kinds of a business.
//
// The caller receives a copy: the order and the content of the list never
// change under it.
func AllKinds() []Kind {
	all := make([]Kind, len(kinds))
	copy(all, kinds)
	return all
}

// Valid reports whether the kind is one of the kinds of a business.
//
// The rule is read from the list of the kinds, so the list and the rule
// never tell two different stories.
func (k Kind) Valid() bool {
	for _, candidate := range AllKinds() {
		if k == candidate {
			return true
		}
	}
	return false
}

// String returns the name of the kind.
//
// It is the name the storage holds, with no translation in between.
func (k Kind) String() string {
	return string(k)
}

// ParseKind returns the kind of the given name.
//
// The storage refuses a name that is not one of the kinds of a business, so a
// name that fails here would fail there too. The error wraps ErrUnknownKind,
// so a caller can tell an unknown kind from a failure of something else.
func ParseKind(name string) (Kind, error) {
	kind := Kind(name)
	if !kind.Valid() {
		return "", fmt.Errorf("%w: %q", ErrUnknownKind, name)
	}
	return kind, nil
}

// The defaults of a business.
const (
	// DefaultPersonalName is the name of the Personal Business of a person.
	//
	// The name is in Spanish because the person reads it in their book, and
	// the identifiers of the code are in English.
	DefaultPersonalName = "Negocio Personal"

	// DefaultCurrency is the currency of a book when the caller has no
	// opinion about it.
	DefaultCurrency = "COP"
)

// Business is a business that owns a book.
type Business struct {
	// ID is the identity of the business. It is empty until the storage
	// writes the row.
	ID ID

	// OwnerID is the document ID of the person who owns the business.
	OwnerID user.ID

	// Kind is the kind of the business.
	Kind Kind

	// Name is the name the person reads.
	Name string

	// Currency is the currency of the book of the business.
	Currency string

	// CreatedAt is the moment the row was created. The storage filled it.
	CreatedAt time.Time

	// UpdatedAt is the moment the row was last written. The storage filled
	// it on insert; whoever updates a row is responsible for it after that.
	UpdatedAt time.Time
}

// New builds a business of the domain.
//
// The name loses the spaces around it, and it may not be empty: a business
// without a name has nothing to show in the book of its owner. The currency
// may not be empty either, and the caller that has no opinion takes the
// default of the domain.
//
// The owner is the person who owns the business, and the identity of the
// business is not set here: the storage generates it, because the number is
// a counter of the business and not a number of the person.
func New(owner user.ID, kind Kind, name, currency string) (Business, error) {
	if !kind.Valid() {
		return Business{}, fmt.Errorf("%w: %q", ErrUnknownKind, kind)
	}

	trimmedName := strings.TrimSpace(name)
	if trimmedName == "" {
		return Business{}, fmt.Errorf("%w: the name of a business is not empty", ErrInvalidName)
	}

	trimmedCurrency := strings.TrimSpace(currency)
	if trimmedCurrency == "" {
		return Business{}, fmt.Errorf("%w: the currency of a business is not empty", ErrInvalidCurrency)
	}

	return Business{
		OwnerID:  owner,
		Kind:     kind,
		Name:     trimmedName,
		Currency: trimmedCurrency,
	}, nil
}

// Personal builds the Personal Business of a person.
//
// The business carries the default name and the default currency of the
// domain, and the person may rename it later.
func Personal(owner user.ID) (Business, error) {
	return New(owner, KindPersonal, DefaultPersonalName, DefaultCurrency)
}
